struct CCompressorZlib_Retail {
    virtual void v00();
    virtual void v01();
    virtual void v02();
    virtual void v03();
    virtual void v04();
    virtual void v05();
    virtual void v06();
    virtual void Decompress(const SCompressedBlock* block, unsigned long blockSize, void* dest, unsigned long destSize, SCompressedBlockInfo* info);   // slot 7 @ 0x00A3ABE0
